GAP = 150
pipes = [[400, 200], [620, 300]]


def update():
    for pipe in pipes:
        pipe[0] = pipe[0] - 2
        if pipe[0] < -76:
            pipe[0] = pipe[0] + 440
            pipe[1] = random_int(80, 300)


def draw():
    clear("skyblue")
    for pipe in pipes:
        draw_sprite("pipe", pipe[0], pipe[1] - 440, flip=True)
        draw_sprite("pipe", pipe[0], pipe[1] + GAP)
